#!/usr/bin/env bash
# Validate a kernel checkpoint generated by mainline/run.sh or retrieved from CI.
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
DIR="${KERNEL_CHECKPOINT_DIR:-$ROOT/out/kernel/checkpoint}"
MODE="${1:---full}"
[ "$MODE" = --basic ] || [ "$MODE" = --full ] || { echo "Usage: $0 [--basic|--full]" >&2; exit 2; }
[ -d "$DIR" ] || { echo "ERROR: Kernel checkpoint missing: $DIR. Build the main branch kernel with bash sh/run.sh first." >&2; exit 1; }
for name in Image.gz sdm632-motorola-channel.dtb kernel.config System.map kernel-release.txt boot-channel.img SHA256SUMS; do
  [ -s "$DIR/$name" ] || { echo "ERROR: Invalid kernel checkpoint: missing $DIR/$name" >&2; exit 1; }
done

#------------------------------------------------------------------#

KREL="$(cat "$DIR/kernel-release.txt")"
[[ "$KREL" =~ ^[-A-Za-z0-9._+]+$ && "$KREL" != *-dirty ]] || {
  echo "ERROR: Invalid kernel release '$KREL'" >&2
  exit 1
}
MOD="$DIR/kernel-modules-$KREL.tar.zst"
[ -s "$MOD" ] || { echo "ERROR: Kernel modules missing: $MOD" >&2; exit 1; }
if [ "$MODE" = --basic ]; then
  echo "Kernel checkpoint present: $KREL ($DIR)"
  exit 0
fi

#------------------------------------------------------------------#

command -v fdtget >/dev/null || { echo 'ERROR: device-tree-compiler missing (fdtget).' >&2; exit 1; }
command -v zstd >/dev/null || { echo 'ERROR: zstd missing.' >&2; exit 1; }
(
  cd "$DIR"
  # Earlier Actions checksums include the out/ prefix; normalize those too.
  sed 's@  out/@  @' SHA256SUMS | sha256sum --check --status -
) || { echo 'ERROR: Kernel checkpoint checksum mismatch.' >&2; exit 1; }
[ "$(fdtget -t s "$DIR/sdm632-motorola-channel.dtb" /soc@0/remoteproc@a204000/iris compatible)" = qcom,wcn3620 ] || {
  echo 'ERROR: Expected WCN3620 iris DTB compatible not present.' >&2; exit 1;
}
for opt in CONFIG_WCN36XX=m CONFIG_QCOM_WCNSS_PIL=m CONFIG_QCOM_WCNSS_CTRL=m CONFIG_USB_CONFIGFS_RNDIS=y CONFIG_USB_DWC3_QCOM=y; do
  grep -Fxq "$opt" "$DIR/kernel.config" || { echo "ERROR: Kernel config lacks $opt" >&2; exit 1; }
done
# Ensure the modules archive actually matches the kernel release.
# Validate the actual Image.gz version and every module's embedded vermagic.
bash "$ROOT/sh/check-kernel-release.sh" "$DIR/Image.gz" "$KREL"
bash "$ROOT/sh/check-modules.sh" "$MOD" "$KREL"
echo "Validated kernel checkpoint: $KREL ($DIR)"
